SELECT a.SEC_SNAME AS `股票名称`, a.SEC_CODE AS `股票代码`, f.ENDDATE AS `报表截止日`, ROUND(f.F110101 / 10000, 1) AS `归母净利润(万)` FROM GET_A_SEC_CODE a INNER JOIN VIEW_STK_FIN_IDX f ON a.COMCODE = f.COMCODE WHERE (a.SEC_SNAME LIKE '%中国平安%' OR a.SEC_SNAME LIKE '%兴业银行%' OR a.SEC_SNAME LIKE '%长江电力%') AND f.ENDDATE = '2025-12-31 00:00:00' AND f.F110101 IS NOT NULL AND a.ISVALID = 1 AND f.ISVALID = 1 ORDER BY f.F110101 DESC LIMIT 1;
